import{d as g,C as t,o as h,c as d,j as i,a as e,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第10章","description":"《中庸》第 10 章——子路问强。南方的含忍、北方的果敢之外，孔子给出君子之强：和而不流、中立而不倚、始终不变。","frontmatter":{"title":"中庸·第10章","description":"《中庸》第 10 章——子路问强。南方的含忍、北方的果敢之外，孔子给出君子之强：和而不流、中立而不倚、始终不变。","category":"guide","aliases":["第10章","中庸第10章","子路问强"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-10.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-10.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-10.md"},f=g({...m,setup(p){const o=[{id:"sanqiang",label:"南方之强 · 北方之强 · 抑而强与",showLabel:!0,sentences:[["子路问强。子曰：“南方之强",{text:"与",glossary:"yu"},"？北方之强与？",{text:"抑",glossary:"yi"},{text:"而",glossary:"er"},"强与？宽柔以教，不报无道，南方之强也，君子居之。",{text:"衽金革",glossary:"renjinge"},"，死而不厌，北方之强也，而强者居之。"]],note:"子路问什么是「强」。孔子先反问：是南方之强、北方之强，还是你自己的强？接着说南方之强：「宽柔以教，不报无道」——以宽厚柔和教人，不报复无道之人，这是君子所居之强；北方之强：「衽金革，死而不厌」——枕着兵器甲胄、至死不怕死，这是勇武之人所居之强。"},{id:"hebutliu",label:"和而不流 · 中立而不倚",showLabel:!0,sentences:[["故君子",{text:"和而不流",glossary:"hebutliu"},"，强哉矫！",{text:"中立而不倚",glossary:"zhonglibuyi"},"，强哉矫！"]],note:"那么君子之强如何？「和而不流」——和顺而不随波逐流；「中立而不倚」——守中而不偏倚。每句之后都以「强哉矫！」（矫＝强盛之貌）赞叹。"},{id:"bubian",label:"国有道不变塞 · 国无道至死不变",showLabel:!0,sentences:[["国有道，不变",{text:"塞",glossary:"se"},"焉，强哉矫！国无道，至死不变，强哉矫！”"]],note:"再进一层：「国有道，不变塞焉」——国家有道时，不改变困穷时的操守；「国无道，至死不变」——国家无道时，至死也不变节。四者合观，才是君子之强。"}],l=[{id:"zilu",term:"子路",pinyin:"zǐ lù",meaning:"孔子弟子仲由，字子路，好勇。朱注以舜（知）、颜渊（仁）、子路（勇）分属三达德，此章正举「勇」。"},{id:"yu",term:"与",pinyin:"yú",meaning:"同「欤」，疑问语气词。读 yú。"},{id:"yi",term:"抑",pinyin:"yì",meaning:"语辞，表选择：还是、或者。"},{id:"er",term:"而",pinyin:"ěr",meaning:"汝、你。「抑而强与」即「还是你所认为的强呢」。"},{id:"renjinge",term:"衽金革",pinyin:"rèn jīn gé",meaning:"衽：卧席；金：戈兵之属；革：甲胄之属。枕戈披甲，即勇于赴战。"},{id:"hebutliu",term:"和而不流",pinyin:"hé ér bù liú",meaning:"和顺而不随波逐流。朱注谓四句皆「汝之所当强也」。"},{id:"zhonglibuyi",term:"中立而不倚",pinyin:"zhōng lì ér bù yǐ",meaning:"守中而立、不偏倚。倚：偏着。"},{id:"se",term:"塞",pinyin:"sè",meaning:"未达、未显达。朱注：「国有道，不变未达之所守；国无道，不变平生之所守也。」"}];return(y,n)=>{const s=t("DaoTextReading"),r=t("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第10章",tabindex:"-1"},[e("中庸·第10章 "),i("a",{class:"header-anchor",href:"#中庸·第10章","aria-label":'Permalink to "中庸·第10章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第十章由子路问强引出。孔子先划开两种「强」——南方之强是"),i("strong",null,"含忍"),e("，北方之强是"),i("strong",null,"果敢"),e("——然后给出君子之强："),i("strong",null,"和而不流、中立而不倚"),e("，以及无论世道如何都不改变。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(s,{colophon:"南方之强 · 北方之强 · 君子之强",tone:"ink",sections:o,glossary:l,"default-mode":"slips","aria-label":"中庸·第10章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(r,{items:[{term:"与",pinyin:["yú"],meaning:"同「欤」，疑问语气词。"},{term:"抑",pinyin:["yì"],meaning:"语辞，表选择：还是。"},{term:"而",pinyin:["ěr"],meaning:"汝、你。「抑而强与」即「还是你所认为的强呢」。"},{term:"衽金革",pinyin:["rèn","jīn","gé"],meaning:"衽：卧席；金：戈兵；革：甲胄。枕戈披甲，勇于赴战。"},{term:"和而不流",pinyin:["hé","ér","bù","liú"],meaning:"和顺而不随波逐流。"},{term:"中立而不倚",pinyin:["zhōng","lì","ér","bù","yǐ"],meaning:"守中而立、不偏倚。倚：偏着。"},{term:"塞",pinyin:["sè"],meaning:"未达、未显达。不变塞，即不改变未达时所守。"}]}),a(r,{items:[{term:"强哉矫",pinyin:["qiáng","zāi","jiǎo"],meaning:"多么刚强啊！矫：强貌。《诗》「矫矫虎臣」即此义。四句连用，是孔子对君子之强的赞叹。"},{term:"自胜其人欲之私",pinyin:["zì","shèng","qí","rén","yù","zhī","sī"],meaning:"朱注解此章云：此四者「非有以自胜其人欲之私，不能择而守也」——正与第 9 章「中庸不可能」相呼应。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>南方之强 · 北方之强 · 抑而强与</strong>：子路问什么是强。孔子说：「是南方所称的强呢？是北方所称的强呢？还是你所认为的强呢？以宽和柔顺教诲人，不报复蛮横无理，这是南方之强，君子取之。枕戈披甲，死而不厌，这是北方之强，强悍者取之。」</p><p><strong>和而不流 · 中立而不倚</strong>：所以君子和顺而不随流，多么刚强啊！守中而不偏倚，多么刚强啊！</p><p><strong>国有道不变塞 · 国无道至死不变</strong>：国有道时，不改变未达时的操守；国无道时，到死也不改变——多么刚强啊！</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十章借子路问强，划清了三种「强」：</p><ul><li><strong>南方之强</strong>：宽柔以教、不报无道——含忍之强，君子取之</li><li><strong>北方之强</strong>：衽金革、死而不厌——果敢之强，强者取之</li><li><strong>君子之强</strong>：和而不流、中立而不倚、国有道不变塞、国无道至死不变</li></ul><p>前两种是「力气」的强，后一种是「守得住」的强。孔子答子路，正落在后者。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「强」从血气移到德义</strong>：朱注说得明白——夫子以此告子路，「所以<strong>抑其血气之刚，而进之以德义之勇</strong>也」。子路好勇，孔子不是否定勇，而是给勇换一个根。</li><li><strong>它与第 9 章接得极紧</strong>：那四条之所以难，朱注说「非有以自胜其人欲之私，不能择而守也」——<strong>又是「私」字</strong>。第 9 章说中庸之难难在无私，本章说君子之强也难在自胜其私。</li><li><strong>「和而不流」「中立而不倚」是一对</strong>：和的难在「不流」（不被带走），中的难在「不倚」（不偏向一边）。这是最难练的两种稳。</li><li><strong>「不变塞」「至死不变」把时间拉长</strong>：强不在一时，而在顺境与逆境都不改。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>分辨我的「强」</strong>：是含忍、是果敢，还是守得住？三者常被混为一谈。</li><li><strong>和而不流</strong>：在群体里能合得来，又没被带走——这是可检验的。</li><li><strong>中立而不倚</strong>：遇分歧时，我有没有自己的判断，还是随大势倒？</li><li><strong>用「境遇」检验</strong>：顺的时候会不会变，难的时候能不能不改？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>子路问什么是强。孔子先反问：你说的是南方的强、北方的强，还是你自己心里的那种强？</p><p>南方的强是<strong>含忍</strong>——宽柔待人，不报复；北方的强是<strong>果敢</strong>——枕戈披甲，不怕死。这两种都算强，但孔子要说的在第三层：<strong>和顺而不随流、守中而不偏倚、顺境不改、逆境到死也不变</strong>——这才叫强。</p><p>一句话：<strong>强不是能扛住多久，而是能不能一直不偏。</strong> 而它的难处，仍在那一个字上：私。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「和而不流」与「中立而不倚」——这两者哪个对我更难？难在什么地方？</li><li>南方之强（含忍）、北方之强（果敢）、君子之强（守得住）——我的「强」更像哪一种？</li><li>「国有道，不变塞；国无道，至死不变」——顺境与逆境，哪一个更容易让我改变？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-09">中庸·第9章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-11">中庸·第11章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{c as __pageData,f as default};
